<script lang="ts">
  import ResourceImage from './ResourceImage.svelte';
  import {isBrowserEdition} from '../core/runtime';
  import {onMount} from 'svelte';
  import {uiIndicator,uiChange,uiCollapse,uiPresence} from '../ui-motion';
  import {Download,Save,Plus,Sparkles,Copy,RotateCcw,Check,UserRound} from '@lucide/svelte';
  import {api} from '../core/editor.svelte';
  import {download} from '../core/download';
  import {twoColorCharacterRecipe,defaultCharacterRecipe,characterVariant,characterAttributeChoices,resolveCharacterVariant,EXPRESSION_OPTIONS,OUTFIT_OPTIONS,ACCESSORY_OPTIONS,SKIN_PRESETS,type CharacterAttribute,type CharacterCatalog,type CharacterRecipe,type CharacterVariant,type SavedCharacterVariant,type CharacterGenerationRequest} from '../core/characters';
  import type {EmbeddedResource} from '../core/resources';
  import AccentPicker from './AccentPicker.svelte';
  let {initialRecipe,initialSavedId,onuse,onback,replace=false,standalone=false}:{initialRecipe?:CharacterRecipe;initialSavedId?:string;onuse?:(data:EmbeddedResource,width:number,height:number)=>Promise<void>;onback?:()=>void;replace?:boolean;standalone?:boolean}=$props();
  let catalog=$state<CharacterCatalog|null>(null),recipe=$state<CharacterRecipe|null>(null),busy=$state(false),error=$state(''),notice=$state(''),ready=$state(false);
  let activeTab=$state<'appearance'|'expression'|'outfit'|'accessory'>('appearance'),name=$state(''),savedId=$state('');
  let showRequest=$state(false),expression=$state('satisfied'),outfit=$state('hoodie'),accessory=$state('none'),details=$state(''),requestPrompt=$state(''),requestUnavailable=$state(false);
  let variant=$derived.by(()=>{try{return catalog&&recipe?characterVariant(catalog,recipe):null;}catch{return null;}});
  let person=$derived(catalog?.characters.find(c=>c.id===recipe?.characterId));
  let available=$derived(catalog?.variants.filter(v=>v.approved&&v.characterId===recipe?.characterId&&v.sceneId===recipe?.sceneId)??[]);
  let saved=$derived(catalog?.saved.filter(v=>v.recipe.characterId===recipe?.characterId)??[]);
  let requests=$derived(catalog?.requests?.filter(v=>v.recipe.characterId===recipe?.characterId)??[]);
  let selectedSaved=$derived(catalog?.saved.find(v=>v.id===savedId));
  let previewTarget=$derived(savedId?`/api/characters/variants/${savedId}/image`:recipe?`/api/characters/preview?${new URLSearchParams({recipe:JSON.stringify(recipe)})}`:'');
  let preview=$state('');
  let previewReady=$derived(ready&&preview===previewTarget);
  let editorLink=$derived(recipe?`${isBrowserEdition?'/app':'/'}?${new URLSearchParams({library:'characters',recipe:JSON.stringify(recipe),...(savedId?{saved:savedId}:{})})}`:'');
  let choices=$derived(catalog&&recipe&&variant&&activeTab!=='appearance'?characterAttributeChoices(catalog,recipe,activeTab):[]);
  let options=$derived(activeTab==='appearance'?[]:Array.from(new Set([...(activeTab==='expression'?EXPRESSION_OPTIONS:activeTab==='outfit'?OUTFIT_OPTIONS:ACCESSORY_OPTIONS).map(v=>v.id),...choices.map(v=>v[activeTab as CharacterAttribute])])).map(id=>({id,variant:choices.find(v=>v[activeTab as CharacterAttribute]===id)})));
  $effect(()=>{const target=previewTarget;ready=false;const timer=setTimeout(()=>preview=target,100);return()=>clearTimeout(timer);});
  onMount(()=>{void api<CharacterCatalog>('/api/characters/catalog').then(value=>{
    catalog=value;
    if(initialSavedId){const record=value.saved.find(v=>v.id===initialSavedId);if(record){recipe=record.recipe;savedId=record.id;name=record.name;}}
    try{const candidate=initialRecipe||JSON.parse(localStorage.getItem('deck-studio-character-recipe')||'null');if(candidate&&!recipe){const validated=twoColorCharacterRecipe(candidate);characterVariant(value,validated);recipe=validated;}}
    catch{/* unavailable local preference falls back to a published master */}
    if(!recipe){const first=value.variants.find(v=>v.approved&&v.id===value.characters[0]?.masterVariantId)||value.variants.find(v=>v.approved);if(first)recipe=defaultCharacterRecipe(first);}
    if(value.warnings?.length)notice=value.warnings.join('; ');
  }).catch(e=>error=e.message);});
  function update(patch:Partial<CharacterRecipe>){if(!recipe)return;try{const next=twoColorCharacterRecipe({...recipe,...patch});if(catalog)characterVariant(catalog,next);recipe=next;savedId='';error='';notice='';requestPrompt='';try{localStorage.setItem('deck-studio-character-recipe',JSON.stringify(recipe));}catch{/* preferences are optional */}}catch(e:any){error=e.message;}}
  function chooseVariant(next:CharacterVariant){update({characterId:next.characterId,sceneId:next.sceneId,variantId:next.id});}
  function chooseContext(target:{characterId?:string;sceneId?:string}){if(!catalog||!recipe)return;if(!variant){const candidates=catalog.variants.filter(v=>v.approved&&v.characterId===(target.characterId||recipe!.characterId));const next=candidates.find(v=>v.sceneId===(target.sceneId||recipe!.sceneId))||candidates[0];if(next)chooseVariant(next);else notice='This character and scene combination is not available yet.';return;}const result=resolveCharacterVariant(catalog,recipe,target);if(!result){notice='This character and scene combination is not available yet.';return;}chooseVariant(result.variant);if(result.changed.length)notice=`Current version: ${result.changed.map(k=>optionLabel(k,result.variant[k])).join(' · ')}`;}
  function choosePerson(id:string){chooseContext({characterId:id});}
  function chooseScene(id:string){chooseContext({sceneId:id});}
  function beginRequest(attribute?:CharacterAttribute,id?:string){if(!variant)return;if(recipe?.renderVersion!=='3')update({});expression=variant.expression;outfit=variant.outfit;accessory=variant.accessory;if(attribute==='expression')expression=id!;if(attribute==='outfit')outfit=id!;if(attribute==='accessory')accessory=id!;details='';requestPrompt='';requestUnavailable=false;showRequest=true;}
  function chooseAttribute(event:Event){if(activeTab==='appearance'||!variant)return;const select=event.currentTarget as HTMLSelectElement,item=choices.find(v=>v[activeTab as CharacterAttribute]===select.value);if(item)chooseVariant(item);else{beginRequest(activeTab,select.value);select.value=variant[activeTab];notice='This version is not available. Save a request below.';}}
  function optionLabel(kind:string,id:string){return (kind==='expression'?EXPRESSION_OPTIONS:kind==='outfit'?OUTFIT_OPTIONS:ACCESSORY_OPTIONS).find(v=>v.id===id)?.label||id;}
  async function save(){if(!recipe||!variant||!name.trim())return;busy=true;error='';try{const record=await api<SavedCharacterVariant>('/api/characters/variants','POST',{name:name.trim(),recipe,baseSha256:variant.sha256});catalog!.saved=[record,...catalog!.saved];savedId=record.id;notice='Variant saved locally';}catch(e:any){error=e.message;}finally{busy=false;}}
  function reopen(id:string){const record=catalog?.saved.find(v=>v.id===id);if(record){recipe=record.recipe;savedId=id;name=record.name;error='';notice='Opened the saved PNG snapshot';}}
  async function rendered(){return api<EmbeddedResource&{width:number;height:number}>('/api/characters/render','POST',savedId?{savedId}:{recipe});}
  async function png(){if(!recipe)return;busy=true;error='';try{const data=await rendered();const blob=await fetch(data.src).then(r=>r.blob());download(blob,`${selectedSaved?.name||recipe.variantId}.png`,'image/png');}catch(e:any){error=e.message;}finally{busy=false;}}
  async function use(){if(!recipe||!onuse)return;busy=true;error='';try{const data=await rendered();await onuse(data,data.width,data.height);}catch(e:any){error=e.message;}finally{busy=false;}}
  async function request(){if(!recipe||requestUnavailable)return;busy=true;error='';try{const value=await api<CharacterGenerationRequest>('/api/characters/requests','POST',{recipe,expression,outfit,accessory,details});catalog!.requests=[value,...(catalog!.requests||[])];requestPrompt=value.prompt;notice='Request saved · Image not generated yet';}catch(e:any){error=e.message;}finally{busy=false;}}
  async function copyPrompt(){try{await navigator.clipboard.writeText(requestPrompt);notice='Generation prompt copied';}catch{error='Clipboard unavailable. Select and copy the prompt manually.';}}
  function reopenRequest(item:CharacterGenerationRequest){if(!catalog)return;requestUnavailable=false;try{characterVariant(catalog,item.recipe);recipe=item.recipe;savedId='';error='';}catch{requestUnavailable=true;notice='The reference asset is no longer available. The original request and prompt are preserved.';}requestPrompt=item.prompt;expression=item.expression;outfit=item.outfit;accessory=item.accessory;details=item.details;showRequest=true;}
</script>

<div class="character-library" aria-busy={busy}>
{#if onback}<button class="text-btn character-back" onclick={onback}>← Back to resource library</button>{/if}
  {#if error}<p class="character-error" role="alert">{error}</p>{/if}
  {#if !catalog||!recipe||(!variant&&!selectedSaved)}<p class="hint">{error?'Character library unavailable':'No reviewed character versions yet'}</p>
  {:else}
    <div class="character-head"><div class="character-people" role="group" aria-label="Character">{#each catalog.characters as character}<button class="text-btn" class:active={recipe.characterId===character.id} aria-pressed={recipe.characterId===character.id} disabled={busy} onclick={()=>choosePerson(character.id)}><UserRound size={15}/>{character.label}</button>{/each}</div><span class="hint">{catalog.characters.length} characters · {catalog.scenes.length} scenes</span></div>
    <div class="character-scenes seg" use:uiIndicator role="group" aria-label="Scene">{#each catalog.scenes as scene}<button aria-pressed={recipe.sceneId===scene.id} disabled={busy} onclick={()=>chooseScene(scene.id)}>{scene.label}</button>{/each}</div>
    <div class="character-workspace">
      <div class="character-art-area"><div class="character-art" aria-busy={!previewReady}>{#key preview}{#if preview}<ResourceImage src={preview} alt="{person?.label||selectedSaved?.characterLabel} · {catalog.scenes.find(s=>s.id===recipe?.sceneId)?.label||selectedSaved?.sceneLabel}" onload={()=>ready=preview===previewTarget} onerror={()=>{ready=false;error='The character preview could not load. Try again.';}} />{/if}{/key}</div><div class="character-art-label"><strong>{person?.label||selectedSaved?.characterLabel}</strong><span>{#if variant}{optionLabel('expression',variant.expression)} · {optionLabel('outfit',variant.outfit)} · {optionLabel('accessory',variant.accessory)}{:else}Saved snapshot · Reference asset unavailable{/if}</span><button class="icon-btn small" aria-label="Reset character to original" title="Reset to original" disabled={busy||!variant} onclick={()=>{if(variant)update(defaultCharacterRecipe(variant));}}><RotateCcw size={14}/></button></div>
        <div class="character-versions" aria-label="Available versions">{#each available as item}<button class:chosen={recipe.variantId===item.id} aria-label="Version:{optionLabel('expression',item.expression)}, {optionLabel('outfit',item.outfit)}, {optionLabel('accessory',item.accessory)}" title="{optionLabel('expression',item.expression)} · {optionLabel('outfit',item.outfit)} · {optionLabel('accessory',item.accessory)}" disabled={busy} onclick={()=>chooseVariant(item)}><ResourceImage src="/resources/characters-v1/{item.file}" alt="" loading="lazy" /><span>{optionLabel('expression',item.expression)} · {optionLabel('outfit',item.outfit)}</span>{#if recipe.variantId===item.id}<Check size={12}/>{/if}</button>{/each}</div>
      </div>
      <aside class="character-controls" aria-label="Customize character">
        <div class="character-tabs" use:uiIndicator role="group" aria-label="Character options">{#each [{id:'appearance',label:'Appearance'},{id:'expression',label:'Expression'},{id:'outfit',label:'Outfit'},{id:'accessory',label:'Accessories'}] as tab}<button class:active={activeTab===tab.id} aria-pressed={activeTab===tab.id} onclick={()=>activeTab=tab.id as typeof activeTab}>{tab.label}</button>{/each}</div>
        <fieldset class="character-adjustments" use:uiChange={activeTab} disabled={!variant}>
        {#if activeTab==='appearance'}
          <div class="character-control-section"><h3>Skin tone mode</h3><div class="seg" use:uiIndicator><button aria-pressed={recipe.skinMode==='classic'} disabled={busy} onclick={()=>update({skinMode:'classic'})}>Original skin tone</button><button aria-pressed={recipe.skinMode==='natural'} disabled={busy} onclick={()=>update({skinMode:'natural'})}>Natural skin tone</button></div></div>
          {#if recipe.skinMode==='natural'}<div class="character-control-section"><h3>Skin tone</h3><div class="character-swatches" role="group" aria-label="Skin tone">{#each SKIN_PRESETS as color}<button style:background={color} aria-label="Skin tone {color}" title={color} aria-pressed={recipe.skinColor===color} disabled={busy} onclick={()=>update({skinColor:color})}></button>{/each}<input type="color" aria-label="Custom skin tone" value={recipe.skinColor} disabled={busy} onchange={e=>update({skinColor:e.currentTarget.value})}/></div></div>{/if}
          <div class="character-control-section"><h3>Clothing and props</h3><AccentPicker label="Clothing and props" value={recipe.clothesColor} disabled={busy} onchange={value=>update({clothesColor:value})}/></div>
        {:else}
          <div class="character-control-section"><h3>{activeTab==='expression'?'Expression':activeTab==='outfit'?'Outfit':'Accessories'}</h3>
            <select aria-label={activeTab==='expression'?'Change expression':activeTab==='outfit'?'Change outfit':'Change accessories'} value={variant?.[activeTab]} disabled={busy} onchange={chooseAttribute}>{#each options as item}<option value={item.id}>{optionLabel(activeTab,item.id)}{item.variant?'':' · Request a version'}</option>{/each}</select>
          </div>
        {/if}
        </fieldset>
        <div class="character-control-section"><label class="field-label">Variant name<input aria-label="Variant name" bind:value={name} maxlength="120" placeholder="For example: Research participant · Project A" disabled={busy}/></label><button class="text-btn ghost full" disabled={busy||!variant||!name.trim()||!previewReady} onclick={save}><Save size={14}/>Save variant</button>{#if saved.length}<label class="field-label saved-label">My variants<select aria-label="Saved character variants" value={savedId} disabled={busy} onchange={e=>reopen(e.currentTarget.value)}><option value="">Choose variant</option>{#each saved as item}<option value={item.id}>{item.name}</option>{/each}</select></label>{/if}</div>
        <div class="character-actions">{#if onuse}<button class="text-btn primary full" disabled={busy||!previewReady} onclick={use}><Plus size={15}/>{replace?'Apply to selected character':'Add to slide'}</button>{:else if standalone}<a class="text-btn primary full" href={editorLink}><Plus size={15}/>Use in Decksprig</a>{/if}<button class="text-btn ghost full" disabled={busy||!previewReady} onclick={png}><Download size={14}/>Download transparent PNG</button><button class="text-btn ghost full" aria-expanded={showRequest} disabled={busy||!variant} onclick={()=>{if(showRequest)showRequest=false;else beginRequest();}}><Sparkles size={14}/>Request a new version</button></div>
        {#if notice}<p class="hint character-notice" in:uiPresence role="status">{notice}</p>{/if}
      </aside>
    </div>
    {#if showRequest}<section class="character-request" transition:uiCollapse><h3>New version request</h3><p class="hint">Save a request and copy its prompt. Generation and review happen separately; saving does not create an image.</p><div class="character-request-fields"><label class="field-label">Expression<select aria-label="Expression for new version" bind:value={expression}>{#each EXPRESSION_OPTIONS as item}<option value={item.id}>{item.label}</option>{/each}</select></label><label class="field-label">Outfit<select aria-label="Outfit for new version" bind:value={outfit}>{#each OUTFIT_OPTIONS as item}<option value={item.id}>{item.label}</option>{/each}</select></label><label class="field-label">Accessories<select aria-label="Accessories for new version" bind:value={accessory}>{#each ACCESSORY_OPTIONS as item}<option value={item.id}>{item.label}</option>{/each}</select></label></div><label class="field-label">Hairstyle, pose, or prop<textarea aria-label="Additional requirements" rows="2" bind:value={details} maxlength="1000"></textarea></label><button class="text-btn primary" disabled={busy||!variant||requestUnavailable} onclick={request}><Save size={14}/>Save generation request</button>{#if requestPrompt}<p class="hint character-notice">Awaiting generation and review</p><textarea aria-label="Generation prompt" readonly value={requestPrompt} rows="5"></textarea><button class="text-btn ghost" onclick={copyPrompt}><Copy size={14}/>Copy prompt</button>{/if}</section>{/if}
  {/if}
  {#if requests.length}<details class="character-request"><summary>Generation requests · {requests.length}</summary><div class="character-request-list">{#each requests as item}<button class="text-btn ghost full" disabled={busy} onclick={()=>reopenRequest(item)}>{catalog?.scenes.find(s=>s.id===item.recipe.sceneId)?.label||item.recipe.sceneId} · {optionLabel('expression',item.expression)} · {optionLabel('outfit',item.outfit)} · Awaiting generation</button>{/each}</div></details>{/if}
</div>

<style>
 .character-adjustments{border:0;padding:0;margin:0;min-width:0}
 .character-library{font-size:var(--ui-label);min-width:0}.character-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:0 0 12px;border-bottom:1px solid var(--border-default)}.character-people{display:flex;gap:4px;flex-wrap:wrap}.character-people .text-btn{min-height:36px}.character-head>.hint{white-space:nowrap}.character-scenes{display:inline-flex;margin:16px 0}.character-scenes button{min-height:34px}.character-workspace{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}.character-art-area{min-width:0}.character-art{width:100%;aspect-ratio:3/2;background:#fff;display:flex;align-items:center;justify-content:center;border:1px solid var(--border-default);border-radius:var(--r-control)}.character-art :global(img){width:100%;height:100%;object-fit:contain}.character-art-label{display:flex;align-items:center;gap:12px;margin:12px 0;font-size:var(--ui-label)}.character-art-label>span{color:var(--text-secondary);flex:1}.character-versions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.character-versions button{position:relative;display:flex;flex-direction:column;align-items:stretch;gap:8px;text-align:left;padding:0 0 4px;min-width:0}.character-versions :global(img){width:100%;aspect-ratio:3/2;object-fit:contain;background:#fff;border:1px solid var(--border-default);border-radius:4px}.character-versions .chosen :global(img){border-color:var(--accent)}.character-versions span{font-size:var(--ui-meta);color:var(--text-secondary);white-space:normal}.character-versions :global(svg){position:absolute;right:5px;top:5px;color:var(--accent)}.character-controls{border-left:1px solid var(--border-default);padding-left:24px;min-width:0}.character-tabs{display:flex;border-bottom:1px solid var(--border-default);gap:16px}.character-tabs button{font-size:var(--ui-label);min-height:36px;border-bottom:2px solid transparent}.character-tabs .active{border-color:transparent;color:var(--text-primary)}.character-control-section{padding:16px 0;border-bottom:1px solid var(--border-subtle)}.character-control-section h3{font-size:var(--ui-label);margin-bottom:12px}.character-swatches{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.character-swatches button{width:24px;height:24px;border-radius:50%;border:2px solid var(--surface-raised);outline:1px solid var(--border-default)}.character-swatches button[aria-pressed=true]{outline:2px solid var(--accent)}.character-actions{display:grid;gap:8px;padding:16px 0}.character-actions a{display:flex;text-decoration:none}.character-error{font-size:var(--ui-label);color:var(--danger-text);margin:0 0 12px}.character-notice{padding:8px 0}.saved-label{margin-top:12px}.character-request{border-top:1px solid var(--border-default);padding:20px 0}.character-request h3{margin-bottom:16px}.character-request-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
 @media(max-width:720px){.character-head{display:block}.character-head>.hint{display:block;margin-top:8px}.character-workspace{grid-template-columns:minmax(0,1fr);gap:16px}.character-controls{border-left:0;padding-left:0}.character-versions{grid-template-columns:repeat(3,minmax(0,1fr))}.character-tabs{justify-content:space-between;gap:12px}.character-tabs button{min-height:44px}.character-swatches button{width:32px;height:32px}.character-actions .text-btn{min-height:44px}.character-request-fields{grid-template-columns:1fr}.character-art-label{flex-wrap:wrap}.character-art-label>span{min-width:55%}.character-scenes{width:100%}.character-scenes button{flex:1}}
</style>
